import React from 'react';
import { HashRouter, Navigate, Route, Routes } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import LoginIntroPage from './pages/login-intro.component';
import OpenDashboardFilePage from './pages/open-dashboard-file.component';
import { FluentProvider, Spinner, teamsLightTheme } from '@fluentui/react-components';
import PrivateRoute from './routing/PrivateRoute';
declare const chrome: any;
export const user_token = window.localStorage.getItem("s365_local_user_token");

function App() {

  const [userAccessToken, setUserAccessToken] = React.useState<string | null>();
  const [isLoggedIn, setIsLoggedIn] = React.useState<boolean>(false);
  const [isLoading, setIsLoading] = React.useState<boolean>(false);
  React.useEffect(() => {
    onInit();

  }, []);
  const onInit = async () => {
    const token = await getUserToken();
    if (!!token) {
      setIsLoggedIn(true);
    }
    setUserAccessToken(token);
  }

  const getUserToken = async () => {
    setIsLoading(true);
    console.log("chrome.webview?.hostObjects?.authService", chrome.webview?.hostObjects?.authService);
    let token = !chrome.webview?.hostObjects?.authService ? user_token : undefined;

    if (chrome.webview?.hostObjects?.authService) {

      const authService = chrome.webview.hostObjects.authService;
      try {
        token = await authService.getUserToken();
      } catch (error) {
        console.log("An error occurred while getting user token", error);
        token = "";
      }
    }
    setIsLoading(false);

    // console.log("App.tsx token", token, !!token);
    return token;
  }

  return <FluentProvider theme={teamsLightTheme}>
    <HashRouter>  <ToastContainer
      position="top-right"
      autoClose={5000}
      hideProgressBar={true}
      newestOnTop={false}
      closeOnClick
      rtl={false}
      pauseOnFocusLoss
      draggable
      pauseOnHover
    /> <div className="App">
        <Routes>
          <Route path="/" element={<PrivateRoute isLoading={isLoading} isLoggedIn={isLoggedIn} />}>
            <Route path="/filepicker/open" element={userAccessToken && <OpenDashboardFilePage userAccessToken={userAccessToken} />} />
            <Route path="/filepicker/save" element={userAccessToken && <OpenDashboardFilePage userAccessToken={userAccessToken} isSaveDialog={true} />} />
          </Route>
          <Route path="/login/intro" element={<LoginIntroPage />} />
          <Route path="/login/intro/:navigateToLogin" element={<LoginIntroPage />} />
        </Routes>
      </div> </HashRouter>
  </FluentProvider>;

}

export default App;
