import { Button, Dialog, DialogActions, DialogBody, DialogContent, DialogSurface, DialogTitle, Label, Radio, RadioGroup } from "@fluentui/react-components";
import { Dismiss24Filled } from "@fluentui/react-icons";
import React, { useState } from "react";
import ReactDOM from "react-dom";
import { useForm } from "react-hook-form";
import { UploadConflictAction } from "../services/dwsim.services";


export type ConflictFormModel = {
    conflictAction: string;

};

type FilesUploadConflictModalProps = {
    onSubmit: (conflictAction: UploadConflictAction) => void,
    onClose: () => void
}

export const FilesUploadConflictModal: React.FC<FilesUploadConflictModalProps> = (props) => {

    const { register, handleSubmit, watch, setError, formState: { errors }, setValue } = useForm<ConflictFormModel>();

    const mapConflictAction = (action: string) => {
        switch (action) {
            case "replace":
                return UploadConflictAction.Overwrite;
            case "keep":
                return UploadConflictAction.KeepBoth;
            default:
                return null;
        }
    };

    const onSubmit = (m: ConflictFormModel) => {
        const conflictAction = mapConflictAction(m.conflictAction);
        props.onSubmit(conflictAction!);

    }

   

    return ReactDOM.createPortal(
        <Dialog
            open={true}>
            <DialogSurface >
                <form onSubmit={handleSubmit(m => onSubmit(m))}>
                    <DialogBody style={{ minHeight: "200px" }}>
                        <DialogTitle action={<Button appearance="transparent" onClick={() => { props.onClose(); }} icon={<Dismiss24Filled />} />}>Upload options</DialogTitle>
                        <DialogContent>

                            <Label id="label8">
                                File already exists.<br />
                                Do you want to replace the existing files with a new version or keep both files?
                            </Label>
                            <RadioGroup aria-labelledby="label8" style={{ marginTop: "var(--spacingVerticalXL)", marginBottom: "var(--spacingVerticalXL)" }}  >
                                <Radio
                                    {...register("conflictAction", { required: true })}
                                    label="Keep both files"
                                    value="keep"
                                />
                                <Radio
                                    {...register("conflictAction", { required: true })}
                                    label="Replace existing files"
                                    value="replace"
                                />
                            </RadioGroup>

                        </DialogContent>
                        <DialogActions>
                            <Button type="submit" appearance="primary" disabled={!!errors.conflictAction}>Save</Button>
                        </DialogActions>
                    </DialogBody>
                </form>
            </DialogSurface>
        </Dialog>
        , document.body);
};