import { CustomFileTypeToIconMap } from './file-type-icon.data';
export function getIconImageUrl(filename, isFolder) {
    if (!filename)
        return undefined;
    var extension = !!isFolder ? "folder" : getFileExtension(filename);
    if (extension && extension != "") {
        for (var iconName in CustomFileTypeToIconMap) {
            var extensions = CustomFileTypeToIconMap[iconName].extensions;
            if (extensions) {
                for (var i = 0; i < extensions.length; i++) {
                    if (extensions[i].toLowerCase() == extension.toLowerCase()) {
                        return CustomFileTypeToIconMap[iconName].imageUrl;
                    }
                }
            }
        }
    }
    if (!isFolder) {
        return CustomFileTypeToIconMap["defaultFile"].imageUrl;
    }
    return undefined;
}
export var getFileExtension = function (filename) {
    if (!filename)
        return undefined;
    var filenameArray = filename.split('.');
    if (filenameArray && filenameArray.length > 1) {
        return filenameArray.pop();
    }
    else {
        return undefined;
    }
};
export var getFileNameWithoutExtension = function (filename) {
    if (!filename) {
        return "";
    }
    var extension = getFileExtension(filename);
    if (!!extension) {
        var nameWithoutExtension = filename.split(".".concat(extension))[0];
        return nameWithoutExtension;
    }
    return "";
};
